declare(strict_types=1); require_once __DIR__ . '/includes/bootstrap.php'; require_once __DIR__ . '/config/app.php'; $connection=db(); $items=cart_items($connection); $success=flash('success'); $error=flash('error'); echo '<style>.brand span{display:none!important}.brand:before{content:"";width:40px;height:40px;border-radius:50%;background:#07182e url("assets/images/sammy-tech-logo.jpeg") center/cover no-repeat;box-shadow:0 0 0 2px #0ea5e9;flex:none}</style>';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your cart | Sammy Tech</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="topbar wrap"><a class="brand" href="index.php"><span>ST</span> SAMMY TECH</a><a class="text-link" href="index.php#shop">← Continue shopping</a></header><main class="wrap simple-page"><p class="eyebrow">Your equipment list</p><h1>Your cart <small><?= cart_count() ?> items</small></h1><?php if($success): ?><p class="flash success"><?=e($success)?></p><?php endif;?><?php if($error): ?><p class="flash error"><?=e($error)?></p><?php endif;?><?php if(!$items): ?><section class="empty"><h2>Nothing here yet.</h2><p>Browse our Starlink equipment, accessories and installation services.</p><a class="button button-dark" href="index.php#shop">Browse equipment</a></section><?php else: ?><div class="cart-layout"><section class="cart-list"><?php foreach($items as $item): ?><article><div><p class="eyebrow"><?=e($item['category_name'])?></p><h3><?=e($item['name'])?></h3><p><?=money((float)$item['price'])?> each · <?=e((string)$item['stock_quantity'])?> available</p></div><form action="actions/cart.php" method="post" class="cart-update"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=e((string)$item['id'])?>"><input type="number" name="quantity" min="1" max="<?=e((string)$item['stock_quantity'])?>" value="<?=e((string)$item['quantity'])?>"><button name="action" value="update">Update</button><button class="remove" name="action" value="remove">Remove</button></form><strong><?=money((float)$item['price']*$item['quantity'])?></strong></article><?php endforeach;?></section><aside class="cart-summary"><p class="eyebrow">Order summary</p><h2><?=money(cart_total($connection))?></h2><p>Delivery cost is confirmed at checkout based on your location.</p><a class="button button-dark" href="checkout.php">Proceed to checkout</a></aside></div><?php endif;?></main></body></html>
